"""
apply_day9.py  -  ONE FILE that upgrades your production-rag project to Day 9.

HOW TO USE (Windows CMD), from inside your production-rag folder:
    .venv\\Scripts\\activate
    python apply_day9.py

What it does:
  1. Backs up every file it is about to change into  _backup_before_day9\\
  2. Writes all Day 1-9 code, tests, scripts, evals and docs into this folder
  3. NEVER touches: .env, .venv, app\\storage, evals\\reports
  4. Runs  pip install -r requirements.txt   (adds prometheus_client)
  5. Runs  python scripts\\verify_day9.py  (tests + a real /ask call + trace/metrics inspection)

Options:
    --no-install    skip pip install
    --no-verify     skip the verification run
    --offline       verification without a live call (free)
    --force         run even if this does not look like a production-rag folder
"""

